declare_lint ! { #[doc = " The `invalid_null_arguments` lint checks for invalid usage of null pointers in arguments."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust,compile_fail"] #[doc = " # use std::{slice, ptr};"] #[doc = " // Undefined behavior"] #[doc = " # let _slice: &[u8] ="] #[doc = " unsafe { slice::from_raw_parts(ptr::null(), 0) };"] #[doc = " ```"] #[doc = ""] #[doc = " {{produces}}"] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " Calling methods whos safety invariants requires non-null ptr with a null pointer"] #[doc = " is [Undefined Behavior](https://doc.rust-lang.org/reference/behavior-considered-undefined.html)!"] INVALID_NULL_ARGUMENTS , Deny , "invalid null pointer in arguments" }